import android.view.accessibility.AccessibilityNodeInfo;
import android.view.accessibility.AccessibilityWindowInfo;
import java.io.FileOutputStream;

/** Verifies and captures the native vertical controls with synthetic speech. */
public final class SidePreview extends Instrumentation {
    private UiAutomation ui;
    private String phase="Starting native side-control checks";
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();try{
        ui=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);
        android.accessibilityservice.AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ui.setServiceInfo(info);
        getTargetContext().startActivity(new Intent().setClassName("app.voiceflow.fixture","app.voiceflow.fixture.EditorActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
        long ready=SystemClock.elapsedRealtime()+45000;while(node("VoiceFlow floating keyboard")==null && SystemClock.elapsedRealtime()<ready)Thread.sleep(150);
        waitNode("Floating keyboard microphone");
        checkSingleRail();
        checkNoEditingKeys();
        checkRight("Floating keyboard microphone");capture("side-preview.png");
        dragMic("Floating keyboard microphone",-28,-36);
        checkNoEditingKeys();check(node("Finish keyboard dictation")==null,"Dragging started recording");
        dragMic("Floating keyboard microphone",28,36);
        Rect idleAnchor=bounds("Floating keyboard microphone");
        holdMic("Floating keyboard microphone");waitTyping(true);waitNode("VoiceFlow: start dictation");
        checkSingleRail();checkAnchor("VoiceFlow: start dictation",idleAnchor,false);check(waitNode("Primary input").isFocused(),"Keyboard toggle defocused the selected input");
        checkNoEditingKeys();check(node("Finish keyboard dictation")==null && node("Finish dictation")==null,"Holding the mic started recording");
        checkKeyboardState("VoiceFlow: start dictation","Keyboard visible");
        longClick("VoiceFlow: start dictation");waitNode("Floating keyboard microphone");waitTyping(false);checkKeyboardState("Floating keyboard microphone","Keyboard hidden");checkNoEditingKeys();
        checkSingleRail();checkAnchor("Floating keyboard microphone",idleAnchor,true);int barWindow=waitNode("Floating keyboard microphone").getWindowId();
        progress("First recording: physical tap and live insertion");tapMic("Floating keyboard microphone");waitText("Primary input","Hello, world");waitNode("Finish keyboard dictation");
        check(node("Finish keyboard dictation").getWindowId()==barWindow,"Recording replaced the control window");
        checkNoEditingKeys();check(node("Cancel keyboard dictation")==null && node("Cancel dictation")==null,"Recording has a cancel control");
        checkRight("Finish keyboard dictation");Rect finish=bounds("Finish keyboard dictation"),wave=bounds("Keyboard recording waveform");check(wave.right<finish.left,"Recording waveform is not on the left of the only Finish control");capture("side-recording.png");
        progress("First recording: Finish");click("Finish keyboard dictation");
        progress("First recording: verify one main bubble after Finish");waitNode("Floating keyboard microphone");checkNoEditingKeys();checkSingleRail();waitText("Primary input","Hello, world");
        Bundle reset=new Bundle();reset.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"Before after");action("Primary input",AccessibilityNodeInfo.ACTION_SET_TEXT,reset);Bundle cursor=new Bundle();cursor.putInt(AccessibilityNodeInfo.ACTION_ARGUMENT_SELECTION_START_INT,7);cursor.putInt(AccessibilityNodeInfo.ACTION_ARGUMENT_SELECTION_END_INT,7);action("Primary input",AccessibilityNodeInfo.ACTION_SET_SELECTION,cursor);Thread.sleep(200);
        progress("Second recording: start after manual reset");click("Floating keyboard microphone");waitText("Primary input","Hello, world");
        progress("Second recording: Finish");click("Finish keyboard dictation");
        progress("Second recording: verify only the main bubble returns");waitNode("Floating keyboard microphone");
        check(node("Floating keyboard microphone").getWindowId()==barWindow,"Finishing replaced the control window");
        checkNoEditingKeys();checkSingleRail();capture("side-finished.png");
        progress("After Finish: verify the main bubble remains minimal while idle");Thread.sleep(17000);waitNode("Floating keyboard microphone");checkNoEditingKeys();checkAnchor("Floating keyboard microphone",idleAnchor,true);
        progress("After Finish: hold to open typing keyboard for editing");holdMic("Floating keyboard microphone");waitTyping(true);waitNode("VoiceFlow: start dictation");
        checkSingleRail();checkAnchor("VoiceFlow: start dictation",idleAnchor,false);
        checkNoEditingKeys();checkKeyboardState("VoiceFlow: start dictation","Keyboard visible");checkAboveKeyboard("VoiceFlow: start dictation");capture("side-keyboard-visible.png");
        progress("Typing keyboard: real Delete and Return keys edit the selected input");checkTypingKeyboardEdits();
        progress("Typing keyboard: another recording and Finish keep only the main bubble");recordAndFinish("VoiceFlow: start dictation",true,barWindow);
        progress("Verify keyboard preference across input and activity changes");action("Second input",AccessibilityNodeInfo.ACTION_FOCUS,null);Thread.sleep(1500);waitTyping(true);waitNode("VoiceFlow: start dictation");checkNoEditingKeys();
        getTargetContext().startActivity(new Intent().setClassName("app.voiceflow.fixture","app.voiceflow.fixture.EditorActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1500);waitTyping(true);waitNode("VoiceFlow: start dictation");checkNoEditingKeys();
        longClick("VoiceFlow: start dictation");waitNode("Floating keyboard microphone");waitTyping(false);checkNoEditingKeys();
        progress("Verify password typing and normal preference restoration");action("Password input",AccessibilityNodeInfo.ACTION_FOCUS,null);waitTyping(true);
        waitNode("VoiceFlow: start dictation");checkSingleRail();checkNoEditingKeys();checkKeyboardState("VoiceFlow: start dictation","Keyboard visible");check(node("Finish dictation")==null && node("Finish keyboard dictation")==null,"Password focus started recording automatically");
        action("Primary input",AccessibilityNodeInfo.ACTION_FOCUS,null);waitNode("Floating keyboard microphone");waitTyping(false);checkNoEditingKeys();
        progress("Verify composer clearance and hide after leaving input");getTargetContext().startActivity(new Intent().setClassName("app.voiceflow.fixture","app.voiceflow.fixture.EditorActivity").putExtra("bottom_composer",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitNode("Bottom input");waitNode("Floating keyboard microphone");waitTyping(false);
        dragOverComposer();checkBottomComposer();checkNoEditingKeys();
        runOnMainSync(()->{android.view.View root=((android.view.ViewGroup)EditorActivity.current.findViewById(android.R.id.content)).getChildAt(0);root.requestFocus();((android.view.inputmethod.InputMethodManager)EditorActivity.current.getSystemService(Activity.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);});waitHidden("Floating keyboard microphone");
        result.putString("result","PASS: one minimal floating dictation bubble on the right with stable anchors across keyboard switches, same recording/finished window, physical tap/hold/drag without accidental recording, direct physical and accessible long-hold keyboard toggle with visible state, one recording Finish control with waveform on the left, direct insertion and retained words, no floating Delete/Enter/menu controls at idle, during recording, after Finish, or across keyboard and field changes; the real typing keyboard Delete/Return keys edit the selected input and another dictation works with typing shown; the bubble stays above the keyboard and clear of the bottom composer, keyboard visibility persists across fields and activity restart, passwords open typing without changing the saved choice, and the bubble hides when focus leaves the input");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("failure",android.util.Log.getStackTraceString(e));result.putString("phase",phase);result.putString("ui_before_finish",diagnostics());finish(Activity.RESULT_CANCELED,result);}}
    private void progress(String value){phase=value;Bundle state=new Bundle();state.putString("phase",value);sendStatus(0,state);}
    private String diagnostics(){StringBuilder out=new StringBuilder();try{for(AccessibilityWindowInfo window:ui.getWindows()){Rect bounds=new Rect();window.getBoundsInScreen(bounds);out.append("window id=").append(window.getId()).append(" type=").append(window.getType()).append(" active=").append(window.isActive()).append(" focused=").append(window.isFocused()).append(" bounds=").append(bounds).append('\n');debugNode(window.getRoot(),out);}}catch(Throwable error){out.append("diagnostics failed: ").append(error);}return out.toString();}
    private void debugNode(AccessibilityNodeInfo node,StringBuilder out){if(node==null)return;node.refresh();CharSequence description=node.getContentDescription();if(description!=null && (description.toString().contains("VoiceFlow") || description.toString().contains("Floating") || description.toString().contains("input"))){Rect bounds=new Rect();node.getBoundsInScreen(bounds);out.append(" node ").append(description).append(" id=").append(node.hashCode()).append(" window=").append(node.getWindowId()).append(" state=").append(node.getStateDescription()).append(" focused=").append(node.isFocused()).append(" visible=").append(node.isVisibleToUser()).append(" bounds=").append(bounds).append('\n');}for(int i=0;i<node.getChildCount();i++)debugNode(node.getChild(i),out);node.recycle();}
    private void checkRight(String description)throws Exception{Rect rect=bounds(description);Bitmap shot=ui.takeScreenshot();int width=shot.getWidth();shot.recycle();check(rect.centerX()>width*.75f,"Controls are not on the right");Rect input=bounds("Primary input");check(!Rect.intersects(rect,input),"Controls cover the selected input");}
    private void checkNoEditingKeys()throws Exception{check(node("Floating Backspace")==null && node("Floating Enter")==null && node("More voice controls")==null && node("Floating Switch keyboard")==null && node("Hide voice controls")==null,"Unnecessary floating editing/menu controls are visible");}
    private void checkSingleRail()throws Exception{long end=SystemClock.elapsedRealtime()+45000;int controls=0;while(SystemClock.elapsedRealtime()<end){controls=0;for(AccessibilityWindowInfo window:ui.getWindows())controls+=countMain(window.getRoot());if(controls==1)return;Thread.sleep(150);}throw new Exception("Expected one visible dictation rail, found "+controls);}
    private int countMain(AccessibilityNodeInfo current){if(current==null)return 0;String description=current.getContentDescription()==null?"":current.getContentDescription().toString();int count=current.isVisibleToUser() && (description.equals("Floating keyboard microphone") || description.equals("VoiceFlow: start dictation") || description.equals("Finish keyboard dictation") || description.equals("Finish dictation"))?1:0;for(int i=0;i<current.getChildCount();i++)count+=countMain(current.getChild(i));return count;}
    private void checkAnchor(String description,Rect expected,boolean restoreY)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){Rect actual=bounds(description);if(Math.abs(actual.centerX()-expected.centerX())<=2 && (!restoreY || Math.abs(actual.centerY()-expected.centerY())<=2))return;Thread.sleep(150);}throw new Exception("Keyboard switch changed the saved dictation anchor");}
    private void checkAboveKeyboard(String description)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){Rect bar=bounds(description);for(AccessibilityWindowInfo window:ui.getWindows())if(window.getType()==AccessibilityWindowInfo.TYPE_INPUT_METHOD){Rect keyboard=new Rect();window.getBoundsInScreen(keyboard);if(keyboard.height()>80 && bar.bottom<keyboard.top)return;}Thread.sleep(150);}throw new Exception("Floating bar did not move above the typing keyboard");}
    private void dragOverComposer()throws Exception{Rect mic=bounds("Floating keyboard microphone"),composer=bounds("Bottom input");long down=SystemClock.uptimeMillis();motion(MotionEvent.ACTION_DOWN,down,mic.centerX(),mic.centerY());Thread.sleep(75);motion(MotionEvent.ACTION_MOVE,down,mic.centerX(),composer.centerY());motion(MotionEvent.ACTION_UP,down,mic.centerX(),composer.centerY());Thread.sleep(300);}
    private void checkBottomComposer()throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){Rect composer=bounds("Bottom input"),bar=bounds("VoiceFlow floating keyboard");AccessibilityNodeInfo input=node("Bottom input");if(bar.bottom<composer.top && input!=null && input.isFocused())return;Thread.sleep(150);}throw new Exception("Floating bar covered or defocused the bottom composer");}
    private void capture(String name)throws Exception{Bitmap shot=ui.takeScreenshot();check(shot!=null,"Native screenshot unavailable");try(FileOutputStream out=new FileOutputStream(getTargetContext().getFilesDir()+"/"+name)){shot.compress(Bitmap.CompressFormat.PNG,100,out);}shot.recycle();}
    private void longClick(String description)throws Exception{action(description,AccessibilityNodeInfo.ACTION_LONG_CLICK,null);Thread.sleep(300);}
    private void checkTypingKeyboardEdits()throws Exception{
        runOnMainSync(()->{android.widget.EditText input=(android.widget.EditText)EditorActivity.current.findViewById(12345);input.setText("Keep X");input.setSelection(input.length());});Thread.sleep(500);
        tapTypingKey("delete","backspace");waitExactInput("Keep ");tapTypingKey("enter","return","new line","newline");waitExactInput("Keep \n");waitTyping(true);waitNode("VoiceFlow: start dictation");checkNoEditingKeys();
    }
    private void waitExactInput(String expected)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){String[] actual={""};boolean[] focused={false};runOnMainSync(()->{android.widget.EditText input=(android.widget.EditText)EditorActivity.current.findViewById(12345);actual[0]=input.getText().toString();focused[0]=input.isFocused();});if(expected.equals(actual[0]) && focused[0])return;Thread.sleep(100);}throw new Exception("The real typing keyboard did not produce the expected selected-input text");}
    private void tapTypingKey(String... labels)throws Exception{
        long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){for(AccessibilityWindowInfo window:ui.getWindows())if(window.getType()==AccessibilityWindowInfo.TYPE_INPUT_METHOD){AccessibilityNodeInfo key=findTypingKey(window.getRoot(),labels);if(key!=null){Rect bounds=new Rect();key.getBoundsInScreen(bounds);key.recycle();check(!bounds.isEmpty(),"Typing key has empty bounds");long down=SystemClock.uptimeMillis();motion(MotionEvent.ACTION_DOWN,down,bounds.centerX(),bounds.centerY());Thread.sleep(75);motion(MotionEvent.ACTION_UP,down,bounds.centerX(),bounds.centerY());return;}}Thread.sleep(150);}throw new Exception("The real typing IME did not expose key bounds for "+java.util.Arrays.toString(labels));
    }
    private AccessibilityNodeInfo findTypingKey(AccessibilityNodeInfo node,String... labels){if(node==null)return null;CharSequence description=node.getContentDescription(),text=node.getText();String name=(description==null?text==null?"":text.toString():description.toString()).trim().toLowerCase(java.util.Locale.ROOT);for(String label:labels)if(label.equals(name) && node.isVisibleToUser())return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo key=findTypingKey(node.getChild(i),labels);if(key!=null){node.recycle();return key;}}node.recycle();return null;}
    private void recordAndFinish(String main,boolean typingVisible,int window)throws Exception{
        tapMic(main);String finish=typingVisible?"Finish dictation":"Finish keyboard dictation";waitNode(finish);checkNoEditingKeys();check(node(finish).getWindowId()==window,"New recording replaced the control window");Thread.sleep(900);tapMic(finish);waitNode(main);checkNoEditingKeys();checkSingleRail();waitTyping(typingVisible);waitText("Primary input","Hello, world");check(node(main).getWindowId()==window,"Finishing a new recording replaced the control window");
    }
    private void motion(int action,long down,float x,float y)throws Exception{MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(ui.injectInputEvent(event,true),"Touch event rejected");event.recycle();}
    private Rect bounds(String description)throws Exception{Rect rect=new Rect();waitNode(description).getBoundsInScreen(rect);return rect;}
    private void tapMic(String description)throws Exception{Rect rect=bounds(description);long down=SystemClock.uptimeMillis();motion(MotionEvent.ACTION_DOWN,down,rect.centerX(),rect.centerY());Thread.sleep(75);motion(MotionEvent.ACTION_UP,down,rect.centerX(),rect.centerY());}
    private void holdMic(String description)throws Exception{Rect rect=bounds(description);long down=SystemClock.uptimeMillis();motion(MotionEvent.ACTION_DOWN,down,rect.centerX(),rect.centerY());Thread.sleep(android.view.ViewConfiguration.getLongPressTimeout()+150);motion(MotionEvent.ACTION_UP,down,rect.centerX(),rect.centerY());Thread.sleep(300);}
    private void dragMic(String description,int dx,int dy)throws Exception{Rect rect=bounds(description);long down=SystemClock.uptimeMillis();motion(MotionEvent.ACTION_DOWN,down,rect.centerX(),rect.centerY());Thread.sleep(75);motion(MotionEvent.ACTION_MOVE,down,rect.centerX()+dx,rect.centerY()+dy);Thread.sleep(android.view.ViewConfiguration.getLongPressTimeout()+100);motion(MotionEvent.ACTION_UP,down,rect.centerX()+dx,rect.centerY()+dy);Thread.sleep(300);Rect after=bounds(description);check(Math.abs(after.centerX()-rect.centerX()-dx)<=2 && Math.abs(after.centerY()-rect.centerY()-dy)<=2,"Drag did not preserve mic position");}
    private void check(boolean okay,String message)throws Exception{if(!okay)throw new Exception(message);}
    private AccessibilityNodeInfo waitNode(String description)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AccessibilityNodeInfo current=node(description);if(current!=null)return current;Thread.sleep(150);}throw new Exception("Missing "+description);}
    private void waitHidden(String description)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){if(node(description)==null)return;Thread.sleep(150);}throw new Exception("Controls stayed visible after leaving the input");}
    private void checkKeyboardState(String description,String expected)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AccessibilityNodeInfo control=node(description);if(control!=null && expected.contentEquals(control.getStateDescription()==null?"":control.getStateDescription()))return;Thread.sleep(150);}throw new Exception("Keyboard state is not accessible: "+expected);}
    private void waitText(String description,String text)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AccessibilityNodeInfo field=node(description);if(field!=null && field.getText()!=null && (text.equals("Before after")?field.getText().toString().equals(text):field.getText().toString().contains(text)))return;Thread.sleep(150);}throw new Exception("Direct text insertion/restoration failed: "+description);}
    private void waitTyping(boolean expected)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){boolean visible=false;for(AccessibilityWindowInfo window:ui.getWindows())if(window.getType()==AccessibilityWindowInfo.TYPE_INPUT_METHOD){Rect bounds=new Rect();window.getBoundsInScreen(bounds);if(bounds.height()>80)visible=true;}if(visible==expected)return;Thread.sleep(150);}throw new Exception("Typing keyboard visibility expected "+expected);}
    private AccessibilityNodeInfo node(String description){for(AccessibilityWindowInfo window:ui.getWindows()){AccessibilityNodeInfo found=find(window.getRoot(),description);if(found!=null)return found;}return null;}
    private AccessibilityNodeInfo find(AccessibilityNodeInfo node,String description){if(node==null)return null;if(description.contentEquals(node.getContentDescription()==null?"":node.getContentDescription()))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo found=find(node.getChild(i),description);if(found!=null)return found;}return null;}
    private void click(String description)throws Exception{action(description,AccessibilityNodeInfo.ACTION_CLICK,null);}
    private void action(String description,int action,Bundle args)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AccessibilityNodeInfo current=node(description);if(current!=null && (args==null?current.performAction(action):current.performAction(action,args)))return;Thread.sleep(150);}throw new Exception("Action "+action+" rejected: "+description);}
}
